mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM users
     WHERE email = #{email}
)

mapper.insert:
INSERT INTO users (
       email
     , password_hash
     , nickname
     , birth_date
     , phone
     , gender
     , address
     , agreed_terms
     , agreed_privacy
     , role
     , status
     , email_verified
) VALUES (
       #{email}
     , #{passwordHash}
     , #{nickname}
     , #{birthDate}
     , #{phone}
     , #{gender}
     , #{address}
     , #{agreedTerms}
     , #{agreedPrivacy}
     , #{role}
     , #{status}
     , #{emailVerified}
)

INSERT INTO user_tokens (
       user_id
     , token_hash
     , purpose
     , expires_at
) VALUES (
       #{userId}
     , #{tokenHash}
     , #{purpose}
     , #{expiresAt}
)

mapper.update:
UPDATE users
   SET email_verified = TRUE
 WHERE user_id = #{userId}
